#==PYTHON_BELOW== (everything below is the program; do not edit)
"""ATLAS: one program that rebuilds everything in the folder it is run from.
  Step 1  ATLAS_Pocket (offline guide) + ATLAS_for_OffGrid (cards + system prompt for the Off Grid app)
  Step 2  download every source book into the library folders (finished files are skipped)
  Step 3  convert every PDF to Markdown, OCR scanned pages, and cut Off Grid-sized parts
Safe to close and re-run at any time.
"""
import base64, csv, json, os, re, shutil, subprocess, sys, time, traceback, urllib.parse
from pathlib import Path

LIB = Path(sys.argv[1].strip('"')).resolve()
# Optional: only these top folders (comma list, e.g. "01_Medical,06_Survival_Navigation") - used by the cloud pack builder.
ONLY = [x.strip() for x in os.environ.get("ATLAS_ONLY", "").split(",") if x.strip()]
OCR_MAX_PAGES = int(os.environ.get("OCR_MAX_PAGES", "100000"))


def wanted(rel):
    return not ONLY or any(rel.replace("\\", "/").startswith(o + "/") or rel.startswith(o + "\\") for o in ONLY)
MAN = LIB / "00_MANIFESTS"
MAN.mkdir(parents=True, exist_ok=True)
LOG = open(MAN / "atlas_run.log", "a", encoding="utf-8")


def log(m=""):
    print(m)
    LOG.write(m + "\n"); LOG.flush()


# =====================================================================  STEP 1: pocket guide + Off Grid kit
def step1():
    log("\n==== STEP 1: offline guide and Off Grid kit ====")
    pocket = LIB / "ATLAS_Pocket"
    for sub in ("cards", "images"):
        (pocket / sub).mkdir(parents=True, exist_ok=True)
    for name, text in CARDS.items():
        (pocket / "cards" / name).write_text(text, encoding="utf-8")
    for name, b64 in IMAGES.items():
        p = pocket / "images" / name
        if not p.exists():
            p.write_bytes(base64.b64decode(b64))
    (pocket / "build_pocket.py").write_text(BUILD_POCKET, encoding="utf-8")
    r = subprocess.run([sys.executable, str(pocket / "build_pocket.py")], cwd=str(pocket))
    log("ATLAS_Pocket\\ATLAS_Pocket.html " + ("built" if r.returncode == 0 else "FAILED to build"))

    og = LIB / "ATLAS_for_OffGrid"
    (og / "Atlas_Cards").mkdir(parents=True, exist_ok=True)
    for name, text in CARDS.items():
        (og / "Atlas_Cards" / name).write_text(text, encoding="utf-8")
    (og / "Atlas_System_Prompt.txt").write_text(OFFGRID_PROMPT, encoding="utf-8")
    (og / "HOW_TO_SET_UP_OFF_GRID.txt").write_text(OFFGRID_HOWTO, encoding="utf-8")
    log("ATLAS_for_OffGrid ready (%d cards)" % len(CARDS))


# =====================================================================  STEP 2: downloads
UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124 Safari/537.36"
CURL = shutil.which("curl.exe") or shutil.which("curl")


def curl(url, out=None, timeout=900):
    cmd = [CURL, "-L", "--fail", "--retry", "1", "--connect-timeout", "25", "--max-time", str(timeout), "-A", UA]
    if out:
        cmd += ["--speed-limit", "5000", "--speed-time", "60", "-#", "-o", str(out), url]
        rc = subprocess.run(cmd).returncode
        if rc != 0:
            raise RuntimeError("download stopped (curl %d%s)" % (rc, {22: " HTTP error/blocked", 28: " timeout", 6: " no DNS", 7: " refused", 35: " TLS", 60: " TLS cert"}.get(rc, "")))
        return b""
    r = subprocess.run(cmd + ["-sS", url], capture_output=True)
    if r.returncode != 0:
        raise RuntimeError("curl exit %d" % r.returncode)
    return r.stdout


def get_json(url):
    return json.loads(curl(url, timeout=60).decode("utf-8", "ignore"))


def words(rel):
    stem = Path(rel).stem
    return [w.lower() for w in re.split(r"[_\-\s]+", stem) if len(w) > 2 and not w.isdigit()
            and w.lower() not in ("the", "and", "for", "vol", "who", "usda", "usn", "fao", "doe", "epa", "cdc", "msu")]


def save_pdf(url, dest, rel, depth=0):
    """Download url to dest. If it is a web page, look for a PDF link on it that matches the title."""
    tmp = dest.with_name(dest.name + ".partial")
    tmp.unlink(missing_ok=True)
    curl(url, out=tmp)
    data_head = tmp.read_bytes()[:5]
    size = tmp.stat().st_size
    if data_head == b"%PDF-" and size > 50_000:
        tmp.replace(dest)
        return size
    page = tmp.read_bytes()[:3_000_000].decode("utf-8", "ignore") if size < 3_000_000 else ""
    tmp.unlink(missing_ok=True)
    if depth == 0 and "<" in page:
        links = set(re.findall(r'href=["\']([^"\']+?\.pdf(?:\?[^"\']*)?)["\']', page, re.I))
        links |= set(re.findall(r'href=["\']([^"\']*(?:/download|/bitstream|/content)[^"\']*)["\']', page, re.I))
        ws = words(rel)
        scored = sorted(links, key=lambda l: -sum(w in l.lower() for w in ws))
        for l in scored[:3]:
            try:
                return save_pdf(urllib.parse.urljoin(url, l), dest, rel, 1)
            except Exception:
                pass
    raise ValueError("not a PDF (%d bytes)" % size)


def archive_url(ident):
    meta = get_json("https://archive.org/metadata/" + urllib.parse.quote(ident))
    files = [f for f in meta.get("files", []) if f.get("name", "").lower().endswith(".pdf")]
    if not files:
        raise ValueError("no PDF in archive item")
    files.sort(key=lambda f: ("Text PDF" in f.get("format", ""), int(f.get("size", 0) or 0)), reverse=True)
    return "https://archive.org/download/%s/%s" % (urllib.parse.quote(ident), urllib.parse.quote(files[0]["name"]))


WHO_API = "https://iris.who.int/server/api"


def who_item_url(item):
    bundles = get_json(item["_links"]["bundles"]["href"])["_embedded"]["bundles"]
    orig = [b for b in bundles if b.get("name") == "ORIGINAL"] or bundles
    bits = get_json(orig[0]["_links"]["bitstreams"]["href"])["_embedded"]["bitstreams"]
    pdfs = [b for b in bits if b.get("name", "").lower().endswith(".pdf")]
    if not pdfs:
        raise ValueError("no PDF on WHO record")
    pdfs.sort(key=lambda b: ("eng" in b["name"].lower(), b.get("sizeBytes", 0)), reverse=True)
    return WHO_API + "/core/bitstreams/%s/content" % pdfs[0]["uuid"]


def who_search_url(q, must):
    objs = get_json(WHO_API + "/discover/search/objects?dsoType=ITEM&size=10&query=" + urllib.parse.quote(q))
    items = [o["_embedded"]["indexableObject"] for o in objs["_embedded"]["searchResult"]["_embedded"]["objects"]]
    items = [i for i in items if all(k in (i.get("name") or "").lower() for k in must)]
    if not items:
        raise ValueError("no WHO match")
    return who_item_url(items[0])


def ia_search_urls(q, must):
    api = ("https://archive.org/advancedsearch.php?q=" + urllib.parse.quote(q + " AND mediatype:texts")
           + "&fl[]=identifier&fl[]=title&sort[]=downloads+desc&rows=10&output=json")
    docs = [d for d in get_json(api)["response"]["docs"]
            if all(k in str(d.get("title") or "").lower() for k in must)]
    return [d["identifier"] for d in docs[:2]]


def resolve(spec):
    """Turn one source spec into a list of candidate PDF URLs (lazily: returns a function)."""
    if spec.startswith("archive:"):
        return [lambda s=spec: archive_url(s[8:])]
    if spec.startswith("who:"):
        return [lambda s=spec: who_item_url(get_json(WHO_API + "/pid/find?id=hdl:" + s[4:]))]
    if spec.startswith("whosearch:"):
        q, m = spec[10:].split("|")
        return [lambda q=q, m=m: who_search_url(q, m.split(";"))]
    if spec.startswith("iasearch:"):
        q, m = spec[9:].split("|")
        return [lambda q=q, m=m, i=i: archive_url(ia_search_urls(q, m.split(";"))[i]) for i in (0, 1)]
    return [lambda s=spec: s]


def fallback_specs(rel):
    ws = words(rel)[:6]
    if len(ws) < 2:
        return []
    q = " AND ".join('title:(%s)' % w for w in ws[:4])
    return ["iasearch:%s|%s" % (q, ";".join(ws[:2]))]


def step2():
    log("\n==== STEP 2: downloading sources (%s) ====" % time.strftime("%Y-%m-%d %H:%M"))
    if not CURL:
        log("curl.exe not found - cannot download."); return
    ok = skip = fail = 0
    failed = []
    fail_why = []
    for line in SOURCES.strip().splitlines():
        parts = line.split("\t")
        rel, specs = parts[0], [p for p in parts[1:] if p]
        if not wanted(rel):
            continue
        dest = LIB / rel
        if dest.exists():
            skip += 1; continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        print("...   %s" % rel)
        done = False
        errs = []
        for spec in specs + fallback_specs(rel):
            for get in resolve(spec):
                try:
                    n = save_pdf(get(), dest, rel)
                    log("OK    %s  %.1f MB" % (rel, n / 1e6)); ok += 1; done = True
                    break
                except Exception as e:
                    print("      (%s: %s)" % (spec[:50], str(e)[:70]))
                    errs.append("%s -> %s" % (spec[:60], str(e)[:80]))
            if done:
                break
        if not done:
            fail += 1; failed.append((rel, specs[0] if specs else "no known source"))
            fail_why.append("%s: %s" % (rel, " ; ".join(errs[-3:]) or "no source"))
            log("FAIL  %s" % rel)
    log("\nDownloads: %d new, %d already there, %d failed" % (ok, skip, fail))
    if os.environ.get("GITHUB_ACTIONS"):
        print("::notice title=Atlas downloads %s::%d new, %d already there, %d failed" % (",".join(ONLY) or "all", ok, skip, fail))
        if fail_why:
            print("::notice title=Atlas failed downloads (why)::%s" % "%0A".join(w.replace("%", "%25") for w in fail_why)[:60000])
    with open(MAN / "MANUAL_DOWNLOADS.txt", "w", encoding="utf-8") as f:
        f.write("Get these by hand if you want them (open the link, save the PDF into the folder shown).\n\n")
        for t, u in MANUAL:
            f.write("%s\n   %s\n\n" % (t, u))
        f.write("---- Failed automatic downloads ----\n")
        for rel, s in failed:
            f.write("%s\n   tried: %s\n" % (rel, s))
    log("List of things to get by hand: 00_MANIFESTS\\MANUAL_DOWNLOADS.txt")


# =====================================================================  STEP 3: convert
SKIP_DIRS = {"10_Kiwix", "_Converted", "00_MANIFESTS", "ATLAS_Pocket", "ATLAS_for_OffGrid"}
PRIORITY = ["01_Medical", "06_Survival_Navigation", "02_Water_Sanitation", "09_Visual_Atlases", "03_Food_Agriculture"]
MIN_CHARS, OCR_DPI, PART_CHARS = 30, 200, 400_000
_ocr, _ocr_failed = None, False


def get_ocr():
    global _ocr, _ocr_failed
    if _ocr is None and not _ocr_failed:
        try:
            from rapidocr_onnxruntime import RapidOCR
            _ocr = RapidOCR()
        except Exception as e:
            _ocr_failed = True
            log("   (OCR engine not available: %s) - scanned pages will be empty" % e)
    return _ocr


def ocr_page(page):
    eng = get_ocr()
    if eng is None:
        return []
    import numpy as np
    pix = page.get_pixmap(dpi=OCR_DPI, alpha=False)
    img = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)
    if pix.n == 1:
        img = np.repeat(img, 3, axis=2)
    result, _ = eng(img[:, :, ::-1].copy())
    k = 72.0 / OCR_DPI
    lines = []
    for box, text, *_ in (result or []):
        xs = [p[0] for p in box]; ys = [p[1] for p in box]
        lines.append((min(xs) * k, min(ys) * k, max(xs) * k, max(ys) * k, text))
    lines.sort(key=lambda l: (round(l[1] / max(1.0, (l[3] - l[1]) * 0.6)), l[0]))
    return lines


def clean(t):
    return "\n".join(ln.rstrip() for ln in t.replace("\x00", "").splitlines()).strip()


def convert_one(fitz, p4l, src, md_path, pdf_path, parts_dir):
    doc = fitz.open(str(src))
    n = doc.page_count
    raw = []
    for i in range(n):
        try:
            raw.append(doc[i].get_text("text") or "")
        except Exception:
            raw.append("")
    md_pages = {}
    if p4l and n <= 1500 and sum(len(t.strip()) >= MIN_CHARS for t in raw) > n * 0.6:
        try:
            for start in range(0, n, 40):
                pages = list(range(start, min(n, start + 40)))
                for p, ch in zip(pages, p4l.to_markdown(doc, pages=pages, page_chunks=True, show_progress=False)):
                    md_pages[p] = ch["text"] if isinstance(ch, dict) else str(ch)
        except Exception as e:
            print("   (markdown formatter failed, plain text used: %s)" % str(e)[:80]); md_pages = {}
    texts, ocr_lines, scanned = [], {}, 0
    for i in range(n):
        if len(raw[i].strip()) >= MIN_CHARS:
            texts.append(clean(md_pages.get(i) or raw[i])); continue
        scanned += 1
        if scanned > OCR_MAX_PAGES:
            texts.append("")
            continue
        try:
            lines = ocr_page(doc[i])
        except Exception as e:
            lines = []; print("   page %d OCR failed: %s" % (i + 1, str(e)[:80]))
        ocr_lines[i] = lines
        texts.append("\n".join(l[4] for l in lines))
        if scanned % 25 == 0:
            print("   ... OCR %d pages (page %d of %d)" % (scanned, i + 1, n))
    title = src.stem.replace("_", " ")
    md_path.parent.mkdir(parents=True, exist_ok=True)
    with open(md_path, "w", encoding="utf-8") as f:
        f.write("# %s\n\nSource file: %s\nPages: %d (scanned/OCR: %d)\n" % (title, src.name, n, scanned))
        for i, t in enumerate(texts):
            f.write("\n\n## Page %d\n\n%s" % (i + 1, t))
    # Off Grid knowledge-base parts: each under 400,000 characters, split on page boundaries
    parts_dir.mkdir(parents=True, exist_ok=True)
    for old in parts_dir.glob(src.stem + "_part*.md"):
        old.unlink()
    buf, k, first = "", 1, 1
    for i, t in enumerate(texts):
        chunk = "\n\n## %s - page %d\n\n%s" % (title, i + 1, t)
        if buf and len(buf) + len(chunk) > PART_CHARS:
            (parts_dir / ("%s_part%02d.md" % (src.stem, k))).write_text("# %s (pages %d-%d)\n%s" % (title, first, i, buf), encoding="utf-8")
            buf, k, first = "", k + 1, i + 1
        buf += chunk
    if buf.strip():
        (parts_dir / ("%s_part%02d.md" % (src.stem, k))).write_text("# %s (pages %d-%d)\n%s" % (title, first, n, buf), encoding="utf-8")
    note = ""
    if scanned and any(ocr_lines.values()) and src.stat().st_size <= 500e6:
        try:
            for i, lines in ocr_lines.items():
                pg = doc[i]
                if pg.rotation:
                    continue
                for x0, y0, x1, y1, text in lines:
                    try:
                        pg.insert_text((x0, y1 - (y1 - y0) * 0.15), text, fontsize=max(4.0, (y1 - y0) * 0.85), render_mode=3)
                    except Exception:
                        pass
            pdf_path.parent.mkdir(parents=True, exist_ok=True)
            doc.save(str(pdf_path), garbage=3, deflate=True)
            note = "ocr_pdf"
        except Exception as e:
            note = "ocr_pdf_failed: %s" % str(e)[:60]
    doc.close()
    return n, scanned, note


def sort_key(rel):
    for i, p in enumerate(PRIORITY):
        if rel.startswith(p + "/"):
            return (i, rel)
    return (len(PRIORITY), rel)


def step3():
    log("\n==== STEP 3: converting PDFs to Markdown + OCR ====")
    try:
        import fitz
    except ImportError:
        log("PyMuPDF did not install, so conversion cannot run. Check your internet and run this file again."); return
    try:
        import pymupdf4llm as p4l
    except Exception:
        p4l = None
    out = LIB / "_Converted"
    out.mkdir(exist_ok=True)
    files = []
    for dp, dn, fn in os.walk(LIB):
        dn[:] = [d for d in dn if d not in SKIP_DIRS]
        files += [str((Path(dp) / f).relative_to(LIB)).replace("\\", "/") for f in fn if f.lower().endswith(".pdf")]
    files = [f for f in files if wanted(f)]
    files.sort(key=sort_key)
    rep_path = out / "CONVERT_REPORT.csv"
    new = not rep_path.exists()
    rep = open(rep_path, "a", newline="", encoding="utf-8")
    w = csv.writer(rep)
    if new:
        w.writerow(["file", "pages", "scanned_pages", "status", "seconds"])
    done = skipped = failed = 0
    for k, rel in enumerate(files, 1):
        src = LIB / rel
        md = (out / "Markdown" / rel).with_suffix(".md")
        if md.exists() and md.stat().st_size > 0 and md.stat().st_mtime >= src.stat().st_mtime:
            skipped += 1; continue
        t0 = time.time()
        print("[%d/%d] %s (%.0f MB)" % (k, len(files), rel, src.stat().st_size / 1e6))
        try:
            n, sc, note = convert_one(fitz, p4l, src, md, (out / "OCR_PDFs" / rel).with_suffix(".pdf"),
                                      out / "OffGrid_Parts" / Path(rel).parent)
            w.writerow([rel, n, sc, ("ok " + note).strip(), "%.0f" % (time.time() - t0)]); done += 1
            print("   done: %d pages, %d scanned, %.0fs %s" % (n, sc, time.time() - t0, note))
        except Exception as e:
            failed += 1
            w.writerow([rel, "", "", "FAILED: " + str(e)[:100], "%.0f" % (time.time() - t0)])
            print("   FAILED: %s" % e); traceback.print_exc(limit=1)
        rep.flush()
    rep.close()
    log("Converted %d, already done %d, failed %d" % (done, skipped, failed))
    if os.environ.get("GITHUB_ACTIONS"):
        print("::notice title=Atlas converted %s::%d converted, %d failed" % (",".join(ONLY) or "all", done, failed))
    make_packs()


def make_packs():
    """Zip the Off Grid parts per top folder so the phone app can import a whole subject at once
    (Projects > knowledge base > package icon)."""
    import zipfile
    parts = LIB / "_Converted" / "OffGrid_Parts"
    packs = LIB / "ATLAS_for_OffGrid" / "Packs"
    packs.mkdir(parents=True, exist_ok=True)
    cards = LIB / "ATLAS_for_OffGrid" / "Atlas_Cards"
    jobs = []
    if cards.exists():
        jobs.append(("00_Atlas_Cards", [p for p in cards.glob("*.md")]))
    if parts.exists():
        for top in sorted(d for d in parts.iterdir() if d.is_dir()):
            jobs.append((top.name, [p for p in top.rglob("*.md")]))
    for name, files in jobs:
        if not files:
            continue
        out = packs / ("%s.zip" % name)
        newest = max(f.stat().st_mtime for f in files)
        if out.exists() and out.stat().st_mtime >= newest:
            continue
        with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
            for f in files:
                z.write(f, f.name if name == "00_Atlas_Cards" else str(f.relative_to(parts / name)))
        log("Pack ready: ATLAS_for_OffGrid\\Packs\\%s.zip (%d files, %.0f MB)" % (name, len(files), out.stat().st_size / 1e6))


# =====================================================================  STEP 4: Kiwix offline encyclopedias (.zim)
KIWIX_BASE = "https://download.kiwix.org/zim/"
KIWIX_DIRS = ["other", "wikipedia", "ifixit", "wikivoyage", "wikihow", "wiktionary"]
KIWIX_WANT = [  # (regex prefix, what it is)
    (r"wikipedia_en_medicine_maxi_", "Wikipedia medicine (WikiMed) with pictures"),
    (r"wikem_en_all_maxi_", "WikEM emergency medicine"),
    (r"zimgit-medicine_en_", "Medicine survival collection"),
    (r"zimgit-post-disaster_en_", "Post-disaster survival collection"),
    (r"zimgit-water_en_", "Water collection"),
    (r"zimgit-food-preparation_en_", "Food preparation collection"),
    (r"zimgit-knots_en_", "Knots"),
    (r"appropedia_en_all_maxi_", "Appropedia appropriate technology"),
    (r"energypedia_en_all_maxi_", "Energypedia small-scale energy"),
    (r"ifixit_en_all_", "iFixit repair guides (phones, electronics)"),
    (r"wikivoyage_en_all_maxi_", "Wikivoyage travel guide (every country)"),
    (r"wikihow_en_maxi_", "wikiHow how-to articles"),
]
KIWIX_BIG = [(r"wikipedia_en_all_nopic_", "ALL of English Wikipedia, no pictures (about 50 GB)", 150)]


def step4():
    log("\n==== STEP 4: Kiwix offline encyclopedias (read them with the free Kiwix app) ====")
    out = LIB / "10_Kiwix"
    out.mkdir(exist_ok=True)
    listing = {}
    for d in KIWIX_DIRS:
        try:
            listing[d] = curl(KIWIX_BASE + d + "/", timeout=60).decode("utf-8", "ignore")
        except Exception as e:
            log("   could not list %s: %s" % (d, e))
    free_gb = shutil.disk_usage(str(LIB)).free / 1e9
    wants = list(KIWIX_WANT) + [(p, w) for p, w, need in KIWIX_BIG if free_gb > need]
    for p, w, need in KIWIX_BIG:
        if free_gb <= need:
            log("SKIP  %s - needs %d GB free, you have %.0f GB" % (w, need, free_gb))
    for prefix, what in wants:
        cands = []
        for d, html in listing.items():
            for name in re.findall(r'href="(%s\d{4}-\d{2}\.zim)"' % prefix, html):
                cands.append((name, d))
        if not cands:
            log("FAIL  %s (not found on the Kiwix server)" % what); continue
        name, d = sorted(cands)[-1]
        dest = out / name
        if dest.exists():
            log("SKIP  %s (already there)" % name); continue
        part = out / (name + ".partial")
        print("...   %s  (%s) - big file, safe to stop and resume" % (name, what))
        cmd = [CURL, "-L", "--fail", "-C", "-", "--retry", "3", "--connect-timeout", "25",
               "--speed-limit", "5000", "--speed-time", "120", "-A", UA, "-#", "-o", str(part), KIWIX_BASE + d + "/" + name]
        r = subprocess.run(cmd)
        if r.returncode == 0 and part.exists() and part.read_bytes()[:4] == b"ZIM\x04":
            for old in out.glob(re.sub(r"\\", "", prefix) + "*.zim"):
                old.unlink()
            part.replace(dest)
            log("OK    %s  %.1f GB" % (name, dest.stat().st_size / 1e9))
        else:
            log("FAIL  %s (stopped - run again to resume)" % name)


# =====================================================================  DATA
CARDS = {'E01_Severe_Bleeding.md': "---\nid: E01\ntitle: Severe bleeding\nzone: Emergency\nkeywords: bleeding, blood, cut, wound, hemorrhage, haemorrhage, pressure, tourniquet, packing, stab, gunshot, shock\nsource: WHO Basic Emergency Care 2018, printed pp.161-162 (PDF pp.169-170) and p.24 (PDF p.32); CDC Open Wound and Bleeding Care 2024\nstatus: Drafted from the sources above. Not reviewed by a clinician.\n---\n## Do this now\n1. Press hard on the bleeding spot with a clean cloth or gauze. Use two or three fingers to press right on the source. A thick bulky pad makes it harder to press in the right place.\n2. If the wound is on an arm or leg, raise it above the heart.\n3. If the cloth soaks through, do NOT pull it off (that tears away the clots). Put another pad on top and keep pressing.\n4. When the bleeding stops, bandage the pad in place.\n\n## If pressure does not stop it\n5. Deep or gaping wound: wash it out with at least 1 litre of clean water if you have it. Then fill the wound completely with gauze or clean folded cloth, put more cloth on top, and press or wrap it firmly. Splint a limb afterward so it does not start bleeding again.\n6. A wound pack is temporary. Do not leave it in more than 24 hours (infection risk).\n\n## Tourniquet: last resort only\nUse ONLY if bleeding is life-threatening and everything above has failed. The limb below it can be permanently damaged or lost.\n- Use a wide band, belt or cloth over padded skin. Wider is better.\n- Arms and legs only. Put it above the bleeding, as close to the wound as you can, but not on the wound and not on a broken bone. The upper arm or thigh works better than below the elbow or knee.\n- Tighten until the bleeding stops and the pulse below it disappears. If it still bleeds, tighten more.\n- Write the exact time on the patient's skin or on the band. Keep it visible.\n- WHO says to get advice or help within 2 hours at most. It should be released every 2 hours for at least 10 minutes while you press on the wound. Do not put it back on unless the bleeding continues.\n\n## Signs of shock (blood loss is making them dangerously ill)\nFast heartbeat, fast breathing, pale cool sweaty skin, dizziness or confusion, and slow color return when you press a fingernail (more than 3 seconds). Lay them flat if they can tolerate it and keep controlling the bleeding.\n\n## Bleeding you cannot see\nBruising around the belly button or sides, blood from the rectum or vagina or in vomit, a broken pelvis or thigh bone, or a chest injury with weak breathing on one side. This needs surgery. Home care cannot fix it. Get them to surgical care if any exists.\n\n## After the bleeding is controlled\nCheck the wound for dirt. Rinse with clean water. Wash the skin around it with soap. Cover with a clean dry dressing. Dirty wounds and punctures: tetanus protection should be reviewed (CDC). Watch for infection: see card M02.\n", 'E02_Snakebite.md': '---\nid: E02\ntitle: Snakebite\nzone: Emergency\nkeywords: snake, snakebite, bite, venom, venomous, antivenom, swelling, rattlesnake, cobra, viper\nsource: CDC/NIOSH "Venomous Snakes at Work" (reviewed Sept 2026), offline snapshot in the ATLAS library\nstatus: Drafted from the source above. Not reviewed by a clinician. The source covers first aid only.\nimage: CDC_PHIL_Snakebite_Hand_24178.jpg\nimage_caption: Severe snakebite injury to a hand: heavy swelling, blood-filled blisters, blue-purple bruising. The snake was not identified. Credit: CDC / Margaret Parsons (public domain).\n---\n## Do this now\n1. Move away from the snake. Do not try to catch or kill it. If you can do it safely from a distance, take a photo of it.\n2. Keep the person calm. Have them sit or lie with the bite in a comfortable, neutral position.\n3. Take off rings and watches now, before the swelling starts.\n4. Wash the bite with soap and water. Cover it with a clean, dry dressing.\n5. Mark the edge of the swelling and the redness with a pen and write the time. Re-mark as it spreads. This shows how fast it is progressing.\n6. Get to emergency medical care as soon as possible. Antivenom may be needed.\n\n## Signs\nAt the bite: puncture marks, bleeding, redness, swelling, bruising, blisters, severe pain and tenderness.\nThrough the body: nausea or vomiting, trouble seeing or breathing, abnormal pulse or blood pressure, sweating or drooling, numbness or tingling, muscle twitching.\n\n## Do NOT\n- Do not put on a tourniquet.\n- Do not cut the wound or suck out venom.\n- Do not use ice or soak the bite in water.\n- Do not use electric shock or folk remedies.\n- Do not try to capture the snake.\n\n## If no medical care exists\nThe source has no further treatment steps. Keep the person still, keep marking the swelling, and watch breathing.\n', 'E03_Cold_Hypothermia_Frostbite.md': '---\nid: E03\ntitle: Hypothermia and frostbite\nzone: Emergency\nkeywords: cold, hypothermia, frostbite, freezing, wet, shivering, winter, warm, rewarm, exposure\nsource: CDC "Preventing Frostbite" / Frostbite and Hypothermia (reviewed Aug 2026), offline snapshot in the ATLAS library\nstatus: Drafted from the source above. Not reviewed by a clinician.\n---\n## Hypothermia (body too cold)\nCan happen even above 40°F (4°C) if the person is wet and chilled.\nSigns: shivering, exhaustion, confusion, fumbling hands, memory loss, slurred speech, drowsiness.\nBody temperature below 95°F (35°C) is an emergency.\n\n### Do this now\n1. Get them into shelter, out of the wind and rain.\n2. Take off wet clothing.\n3. Warm the body under dry layers.\n\n## Frostbite (frozen skin)\nSigns: skin that is red or painful, then turns white or gray-yellow, feels unusually hard or waxy, and goes numb.\n\n### Do this\n- Rewarm the area in warm water that feels warm to the touch, not hot.\n- Avoid walking on frostbitten feet or toes unless you have to.\n\n### Do NOT\n- Do not rub or massage frostbitten skin.\n- Do not warm with a fireplace, stove, heat lamp, heating pad or any strong direct heat.\n', 'M01_Diarrhea_Dehydration_Drink.md': '---\nid: M01\ntitle: Diarrhea and dehydration: home rehydration drink\nzone: Illness\nkeywords: diarrhea, diarrhoea, vomiting, dehydration, rehydration, ORS, thirsty, dry, sugar, salt, cholera, child, baby\nsource: Where There Is No Doctor (Werner, 2010), printed p.152 (PDF p.199)\nstatus: Recipe copied from the source. Not reviewed by a clinician.\n---\n## Why this matters\nWith watery diarrhea, the danger is losing too much water. Plenty of drink and food matters more than any medicine. Most diarrhea can be treated at home.\n\n## Make the drink (pick one)\n**A. Sugar and salt**\n- 1 liter of clean water\n- half a level teaspoon of salt\n- 8 level teaspoons of sugar (raw sugar or molasses will do)\nTaste it before adding the sugar. It must be less salty than tears.\n\n**B. Cereal and salt** (often better, and safer than packets)\n- 1 liter of water\n- half a teaspoon of salt\n- 8 heaping teaspoons (or 2 handfuls) of powdered cereal. Powdered rice is best. Fine maize, wheat flour, sorghum, or cooked mashed potato work.\n- Boil for 5 to 7 minutes into a thin porridge. Cool quickly.\nTaste it each time before you give it. Cereal drinks can spoil in a few hours in hot weather.\n\nAdd half a cup of fruit juice, coconut water or mashed ripe banana to either drink if you have it. The potassium may help them accept more food and drink.\nIf you have no liter measure or teaspoon, adapt to local measures.\n\n## How to give it\n- Sips every 5 minutes, day and night, until they start to urinate normally.\n- A large person needs 3 liters or more a day. A small child needs at least 1 liter a day, or 1 glass for each watery stool.\n- Keep giving it in small sips even if they vomit. Not all of it comes back up.\n- Keep feeding as soon as they will eat. Babies: keep breast-feeding, often, before other drinks.\n- Thin cereal porridge, soup, tea or plain water are better than nothing.\n\n## Warning\nIf dehydration gets worse or other danger signs appear, they need real medical help. The source (p.159) lists the danger signs. They may need liquid given into a vein.\n', 'M02_Infected_Wound_Sepsis.md': '---\nid: M02\ntitle: Infected wound, abscess and blood poisoning (sepsis)\nzone: Illness\nkeywords: infection, infected, pus, abscess, cellulitis, red, swollen, hot, fever, sepsis, blood poisoning, wound, antibiotic\nsource: CDC "Wound Infection, Cellulitis, and Sepsis" (2026) and CDC Open Wound and Bleeding Care (2024), offline snapshots in the ATLAS library\nstatus: Drafted from the sources above. Not reviewed by a clinician. No antibiotic doses on this card.\nimage: CDC_PHIL_Cellulitis_20275.jpg\nimage_caption: Cellulitis with pus. Credit: CDC PHIL #20275 (public domain). A photo cannot tell you the cause, the depth, or which drug.\nimage2: CDC_PHIL_MRSA_Abscess_7824.jpg\nimage2_caption: Abscess (pus-filled lump) on a knee. Credit: CDC PHIL #7824 (public domain). Do not guess the germ or the treatment from how it looks.\n---\n## Keep a wound from getting infected\n- Control bleeding first (card E01).\n- Check for dirt or objects in the wound. Rinse well with clean running water.\n- Wash the skin around it with soap and clean water.\n- Cover with a clean dry bandage. Change it when it is wet or dirty.\n- Do not close a dirty bite or puncture wound in a way that traps dirt inside.\n- Wash your hands before and after.\n- Dirty wounds and punctures: tetanus protection should be reviewed.\n\n## Signs of a skin infection (cellulitis)\nPainful, red, swollen, tender and warm skin. Skin that looks pitted like orange peel, or blisters. Fever and chills may come with it.\nFast-spreading redness, or fever and chills: urgent.\n\n## Signs it is spreading through the body (sepsis)\nAlmost any infection can do this. Watch for:\n- clammy or sweaty skin\n- confusion\n- extreme pain or discomfort\n- fever, shivering, or feeling very cold\n- fast heartbeat or weak pulse\n- shortness of breath\nAny of these with an infected wound is an emergency.\n\n## What to do\n1. Keep cleaning and covering the wound.\n2. ATLAS addition (not in the CDC sources): mark the edge of the redness with a pen and write the time, so you can see if it is spreading.\n3. ATLAS addition (not in the CDC sources): keep the person drinking. See card M01 for a rehydration drink.\n4. If you have proper antibiotics, the right choice depends on the infection. This card does not cover that. Do not guess.\n5. Get medical care if any sepsis sign appears.\n', 'MH01_Someone_Talking_About_Suicide.md': '---\nid: MH01\ntitle: Someone is talking about suicide or self-harm\nzone: Mind\nkeywords: suicide, suicidal, self-harm, self harm, kill myself, hopeless, despair, depressed, overdose, crisis, mental health, 988\nsource: WHO mhGAP Intervention Guide v2.0 (2016), Self-harm/Suicide module SUI 1 and SUI 2, printed pp.133-136 (PDF pp.141-144)\nstatus: Drafted from the source above. Not reviewed by a clinician.\n---\n## If you are the one having these thoughts\nATLAS addition (not from the WHO guide): tell another person today and ask them to stay with you. Put anything you could hurt yourself with out of reach. In the US with phone service: call or text 988.\n\n## Warning signs to ask about (from the WHO guide)\nExtreme hopelessness and despair. Current thoughts, a plan, or an act of self-harm, or a history of it. Signs of poisoning or intoxication. Bleeding from a self-inflicted wound. Loss of consciousness or extreme lethargy.\nAsk the person directly, and ask the people close to them: are there current thoughts or a plan of self-harm or suicide? Any thoughts or plan in the past month, or an act in the past year, in someone who is now very agitated, violent, distressed or not communicating?\n\n## 1. They have already hurt themselves seriously\n- Treat the injury or poisoning first. Do not leave them alone.\n- Put them somewhere safe and supportive.\n- Keep close watch even after they are medically stable.\n\n## 2. Imminent risk (thoughts or a plan now)\n- Remove the means to harm themselves.\n- Do not leave the person alone. Name one person who stays with them at all times.\n- Keep them in a quiet, safe place.\n- Attend to how they feel and what they are going through. Explain to them and the people caring for them what is happening (the guide calls this psychoeducation).\n- Support the carers too.\n- Ask for a mental health specialist if one exists.\n- Keep regular contact afterward.\n\n## 3. Thoughts or an attempt in the past month or year, but no immediate plan\n- Offer and arrange psychosocial support.\n- Keep in regular contact and follow up.\n\n## Also check for\nDepression, psychosis, alcohol or drug problems, epilepsy, or chronic pain. Treating these lowers the risk. See the matching WHO module. This card has the self-harm module only.\n', 'MH02_Stopping_Alcohol_or_Sedatives.md': "---\nid: MH02\ntitle: Stopping alcohol or sedatives suddenly (withdrawal)\nzone: Mind\nkeywords: withdrawal, alcohol, drinking, benzodiazepine, valium, xanax, diazepam, sedative, seizure, delirium, tremor, shaking, opioid, detox\nsource: WHO mhGAP Intervention Guide v2.0 (2016), Substance use module SUB 2, printed pp.110-112 (PDF pp.118-120)\nstatus: Copied from the source, which is written for clinicians. Not reviewed by a clinician. Doses apply only if you actually have the medicine.\n---\n## Why this is serious\nStopping alcohol or sedatives (benzodiazepines such as diazepam) suddenly can cause seizures and delirium. These are emergencies.\n\n## Signs of withdrawal\nTremors (shaking), sweating, vomiting, raised blood pressure and heart rate, agitation.\nLater, within about a week of the last drink: confusion, hallucinations, racing thoughts, anxiety, not knowing where or when they are. That is delirium.\n\n## What the WHO guide says\nFor tremors, sweating or changed vital signs:\n- Diazepam 10-20 mg by mouth, and transfer to hospital or a detox facility if possible.\n- Watch the person and repeat doses as needed if signs continue.\n- Alcohol withdrawal only: thiamine (vitamin B1) 100 mg daily for five days.\n\nSend to hospital immediately if there is another serious problem (liver failure confusion, stomach or gut bleeding, head injury), or:\n- Seizures: give diazepam 10-20 mg first (by mouth, vein or rectum).\n- Delirium: give diazepam 10-20 mg first. If severe and diazepam is not enough, the guide names haloperidol 1-2.5 mg by mouth or injection.\n\nConfusion has other causes too: head injury, low blood sugar, stroke, pneumonia or other infection, liver failure. Check for those.\n\n## Opioid withdrawal (WHO guide)\nSigns: wide pupils, muscle aches, stomach cramps, headache, nausea, vomiting, diarrhea, runny eyes and nose, anxiety, restlessness.\nGuide's treatment: methadone 20 mg (extra 5-10 mg after 4 hours if needed), or buprenorphine 4-8 mg (extra dose after 12 hours if needed). If neither is available, any opioid can be used short-term. The guide also mentions clonidine or lofexidine.\n\n## Remember\nThe danger is in stopping suddenly. Someone who is dependent and has no supply is at risk. Do not leave them alone.\n", 'PW01_Phone_Power_and_Battery.md': "---\nid: PW01\ntitle: Phone power: charge it, ration it, protect it\nzone: Power and tools\nkeywords: phone, battery, charge, charging, solar, power bank, USB, car, 12V, lithium, electricity, power, tablet, ration\nsource: ATLAS general guidance. NOT taken from a library source. Common practice; check against the manual of your own devices and panels.\nstatus: Unsourced synthesis. Not reviewed by anyone. Treat as a checklist, not as authority.\n---\n## Make the battery last\n1. Airplane mode. Searching for signal drains the battery fast.\n2. Lowest comfortable screen brightness. Close other apps. Use the phone's low-power mode.\n3. Running a local AI uses a lot of power. Reading a card in this guide uses very little. Use the AI only when you need something explained, and ask in one batch.\n4. Cold weakens a battery. Keep the phone in an inside pocket. Do not charge it frozen.\n5. Keep it dry and out of direct hot sun.\n6. Copy the most important cards onto paper early, while you have power.\n\n## What can charge a phone\nPhones charge from USB (5 volts).\n- A power bank. The best backup to carry.\n- A folding solar panel that has a USB output. The USB output regulates the power for you.\n- A car's 12-volt socket with a USB adapter (engine running or battery still charged).\n- A laptop's USB port.\n\n## What can damage it\n- Do not wire a bare solar panel, a car battery, or a wall adapter of unknown output straight to a phone cable. Voltage is much higher than 5 volts and can destroy the phone.\n- Do not charge a battery that is swollen, very hot, or leaking. Stop using it.\n- Do not puncture or crush a phone or power bank.\n\n## When salvaging\nReady-made USB devices (power banks, car adapters, USB-output solar chargers) can be reused safely. Making your own power supply from raw parts needs electronics knowledge not covered by this card.\n\n## If power runs out\nThe cards on paper are your guide. Keep them dry.\n", 'W01_Make_Water_Safe.md': '---\nid: W01\ntitle: Make water safe to drink\nzone: Water and food\nkeywords: water, drinking, boil, bleach, chlorine, iodine, purify, disinfect, filter, river, lake, well, dirty water\nsource: US EPA "Emergency Disinfection of Drinking Water" EPA 816-F-15-003 (Sept 2017), pp.1-2\nstatus: Quantities copied from the source. Not reviewed by a clinician.\n---\n## First\nIf the water is cloudy, let it settle, then pour it through a clean cloth, paper towel or coffee filter. Disinfection works less well in cloudy water.\nFlowing water is better than still water. Do not use water with floating material in it, a dark color, or a bad smell.\n\n## Best method: boil\n1. Bring to a rolling boil for at least 1 minute.\n2. Above 5,000 feet (1,000 m): boil for 3 minutes.\n3. Let it cool by itself. Store in clean covered containers.\n4. Flat taste: add a pinch of salt per liter, or pour between two clean containers.\n\n## No fuel: plain liquid bleach\nUse regular unscented bleach (6% or 8.25% sodium hypochlorite). No scented, color-safe, or added-cleaner bleach. Bleach older than 1 year is weaker.\nAdd this much to clean water:\n- 1 quart or liter: 2 drops (either strength)\n- 1 gallon: 8 drops of 6%, or 6 drops of 8.25%\n- 2 gallons: 16 drops (1/4 tsp) of 6%, or 12 drops (1/8 tsp) of 8.25%\n- 4 gallons: 1/3 tsp of 6%, or 1/4 tsp of 8.25%\n- 8 gallons: 2/3 tsp of 6%, or 1/2 tsp of 8.25%\nDouble the amount if the water is cloudy, colored or very cold.\nStir. Wait 30 minutes. It should smell slightly of chlorine. If it doesn\'t, repeat the dose and wait 15 more minutes.\nToo strong a taste: pour between clean containers and let it stand a few hours.\n\n## Other methods from the same source\n- Tincture of iodine, 2%: 5 drops per quart or liter. If cloudy or colored: 10 drops. Stir and wait at least 30 minutes.\n- Purification tablets (chlorine, iodine, chlorine dioxide): follow the label, strengths differ.\n- Calcium hypochlorite (HTH) powder: dissolve 1 heaping teaspoon (about 1/4 oz) in 2 gallons of water to make a stock. Add 1 part stock to every 100 parts of water to treat (about 1 pint of stock per 12.5 gallons). Do this in open air with eye protection. HTH is a strong oxidizer.\n\n## What this does NOT fix\nBoiling and chemicals kill disease germs. They do not remove heavy metals, salts, fuel or most other chemicals.\n'}

