BUILD_POCKET = '#!/usr/bin/env python3\n"""\nATLAS Pocket builder.  Turns the cards in  cards\\\\*.md  (+ pictures in images\\\\)\ninto ONE self-contained file:  ATLAS_Pocket.html\n\nOpen that file in any phone or computer browser. It works offline: no app, no internet.\n  - Big buttons by urgency, plus a plain keyword search\n  - One short card per topic, with source and page numbers\n  - "Copy for AI" button: copies the card plus instructions, ready to paste into PocketPal\nOnly needs Python 3 (no extra packages).\n\n    python build_pocket.py            (run from inside the ATLAS_Pocket folder)\n\nCard format (cards\\\\ID_Name.md):  a header between two --- lines, then the card text.\n  id, title, zone, keywords, source, status           (all required)\n  image, image_caption, image2, image2_caption        (optional; file names inside images\\\\)\nBody: "## Heading", "### Subheading", "- bullet", "1. numbered", **bold**, blank line = new paragraph.\n"""\nimport base64, html, json, re, sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nZONES = [  # (zone name in the card header, button label, one-line hint, css color)\n    ("Emergency", "Emergency", "Minutes matter", "#c62828"),\n    ("Water and food", "Water and food", "Days", "#1565c0"),\n    ("Illness", "Illness and injury care", "Hours to weeks", "#ef6c00"),\n    ("Mind", "Mind and crisis", "Safety first", "#6a1b9a"),\n    ("Power and tools", "Power and tools", "Keep the device alive", "#2e7d32"),\n]\nAI_PREFIX = (\n    "Use ONLY the card below to answer. Reply in short numbered steps. Quote numbers and amounts exactly as "\n    "written. If the card does not cover my question, say: \'This card does not cover that.\' Never invent doses, "\n    "amounts or times. Put the most urgent step first.\\n\\n"\n)\nAI_SUFFIX = "\\n\\nMY QUESTION: "\n\n\ndef parse(path: Path):\n    t = path.read_text(encoding="utf-8")\n    m = re.match(r"---\\s*\\n(.*?)\\n---\\s*\\n(.*)$", t, re.S)\n    if not m:\n        sys.exit(f"{path.name}: missing header (--- block)")\n    meta = {}\n    for line in m.group(1).splitlines():\n        if ":" in line:\n            k, v = line.split(":", 1)\n            meta[k.strip()] = v.strip()\n    for k in ("id", "title", "zone", "keywords", "source", "status"):\n        if k not in meta:\n            sys.exit(f"{path.name}: header is missing \'{k}\'")\n    meta["body"] = m.group(2).strip()\n    return meta\n\n\ndef inline(s):\n    s = html.escape(s)\n    return re.sub(r"\\*\\*(.+?)\\*\\*", r"<strong>\\1</strong>", s)\n\n\ndef render(body):\n    out, para, lst = [], [], None\n\n    def flush_p():\n        nonlocal para\n        if para:\n            out.append("<p>" + inline(" ".join(para)) + "</p>"); para = []\n\n    def flush_l():\n        nonlocal lst\n        if lst:\n            tag, items = lst\n            out.append(f"<{tag}>" + "".join(f"<li>{inline(i)}</li>" for i in items) + f"</{tag}>"); lst = None\n\n    for line in body.splitlines():\n        s = line.rstrip()\n        if not s.strip():\n            flush_p(); flush_l(); continue\n        if s.startswith("### "):\n            flush_p(); flush_l(); out.append(f"<h3>{inline(s[4:])}</h3>"); continue\n        if s.startswith("## "):\n            flush_p(); flush_l(); out.append(f"<h2>{inline(s[3:])}</h2>"); continue\n        mb = re.match(r"^\\s*[-*] (.*)", s)\n        mn = re.match(r"^\\s*\\d+\\. (.*)", s)\n        if mb or mn:\n            flush_p()\n            tag = "ul" if mb else "ol"\n            if lst and lst[0] != tag:\n                flush_l()\n            if not lst:\n                lst = (tag, [])\n            lst[1].append((mb or mn).group(1)); continue\n        flush_l(); para.append(s.strip())\n    flush_p(); flush_l()\n    return "\\n".join(out)\n\n\ndef plain(c):\n    b = re.sub(r"\\*\\*(.+?)\\*\\*", r"\\1", c["body"])\n    b = re.sub(r"^#{2,3} (.*)$", lambda m: "\\n" + m.group(1).upper(), b, flags=re.M)\n    return (f"CARD {c[\'id\']}: {c[\'title\']}\\nSOURCE: {c[\'source\']}\\n\\n{b.strip()}\\n\\nEND OF CARD {c[\'id\']}").strip()\n\n\ndef img_tag(name, cap):\n    p = HERE / "images" / name\n    if not p.exists():\n        print(f"WARNING: image missing: {name}"); return ""\n    mime = "image/png" if p.suffix.lower() == ".png" else "image/jpeg"\n    data = base64.b64encode(p.read_bytes()).decode()\n    return (f\'<figure><img src="data:{mime};base64,{data}" alt="{html.escape(cap)}">\'\n            f"<figcaption>{html.escape(cap)}</figcaption></figure>")\n\n\ndef main():\n    cards = [parse(p) for p in sorted((HERE / "cards").glob("*.md"))]\n    ids = [c["id"] for c in cards]\n    if len(ids) != len(set(ids)):\n        sys.exit("Duplicate card ids: " + ", ".join(sorted({i for i in ids if ids.count(i) > 1})))\n    zone_names = {z[0] for z in ZONES}\n    for c in cards:\n        if c["zone"] not in zone_names:\n            sys.exit(f"{c[\'id\']}: unknown zone \'{c[\'zone\']}\'. Allowed: {sorted(zone_names)}")\n\n    data = []\n    for c in cards:\n        figs = ""\n        for k in ("image", "image2"):\n            if c.get(k):\n                figs += img_tag(c[k], c.get(k + "_caption", ""))\n        body_html = render(c["body"])\n        data.append({\n            "id": c["id"], "title": c["title"], "zone": c["zone"], "keywords": c["keywords"],\n            "source": c["source"], "status": c["status"], "figs": figs, "html": body_html,\n            "ai": AI_PREFIX + plain(c) + AI_SUFFIX, "search": (c["title"] + " " + c["keywords"] + " " + c["body"]).lower(),\n        })\n\n    page = TEMPLATE.replace("__CARDS__", json.dumps(data).replace("</", "<\\\\/")) \\\n                   .replace("__ZONES__", json.dumps([dict(key=z[0], label=z[1], hint=z[2], color=z[3]) for z in ZONES]))\n    out = HERE / "ATLAS_Pocket.html"\n    out.write_text(page, encoding="utf-8")\n    print(f"Built {out.name}: {len(cards)} cards, {out.stat().st_size/1e6:.2f} MB")\n\n\nTEMPLATE = r"""<!doctype html>\n<html lang="en"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>ATLAS Pocket</title>\n<style>\n:root{--bg:#fafaf7;--fg:#1b1b1b;--mut:#5d5d5d;--card:#fff;--line:#d9d9d2;--accent:#1b1b1b;--warn:#fff3cd;--warnb:#e0b94a}\n@media (prefers-color-scheme:dark){:root{--bg:#121212;--fg:#ececec;--mut:#a5a5a5;--card:#1c1c1c;--line:#363636;--warn:#3a3114;--warnb:#8a7020}}\n*{box-sizing:border-box}\nhtml{font-size:18px}\nbody{margin:0;background:var(--bg);color:var(--fg);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;line-height:1.5}\nmain{max-width:46rem;margin:0 auto;padding:1rem 16px 4rem}\nh1{font-size:1.5rem;margin:.2rem 0}\nh2{font-size:1.15rem;margin:1.4rem 0 .4rem;padding-top:.6rem;border-top:1px solid var(--line)}\nh3{font-size:1.02rem;margin:1rem 0 .2rem}\n.sub{color:var(--mut);margin:0 0 1rem}\ninput[type=search]{width:100%;font-size:1.05rem;padding:.8rem 1rem;border:2px solid var(--line);border-radius:12px;background:var(--card);color:var(--fg)}\n.zones{display:grid;gap:.6rem;margin:1rem 0}\n.zone{display:block;width:100%;text-align:left;border:0;border-left:8px solid var(--c);border-radius:10px;background:var(--card);color:var(--fg);padding:.9rem 1rem;font-size:1.05rem;font-weight:600;box-shadow:0 1px 0 var(--line);cursor:pointer}\n.zone small{display:block;font-weight:400;color:var(--mut)}\n.list a,.res a{display:flex;gap:.7rem;align-items:baseline;padding:.8rem .2rem;border-bottom:1px solid var(--line);text-decoration:none;color:var(--fg)}\n.list a b,.res a b{min-width:3.2rem;color:var(--c,var(--mut));font-variant-numeric:tabular-nums}\n.chip{display:inline-block;font-size:.8rem;font-weight:700;color:#fff;background:var(--c);padding:.1rem .6rem;border-radius:99px}\n.back{display:inline-block;margin:.2rem 0 .8rem;padding:.5rem .9rem;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--fg);text-decoration:none;font-size:.95rem}\n.tools{display:flex;gap:.6rem;flex-wrap:wrap;margin:.8rem 0}\nbutton.act{font-size:1rem;padding:.7rem 1rem;border-radius:10px;border:2px solid var(--fg);background:var(--fg);color:var(--bg);font-weight:600;cursor:pointer}\nbutton.act.alt{background:transparent;color:var(--fg)}\nol,ul{padding-left:1.4rem}li{margin:.35rem 0}\nfigure{margin:1rem 0}figure img{max-width:100%;height:auto;border-radius:8px}figcaption{font-size:.85rem;color:var(--mut)}\n.note{background:var(--warn);border:1px solid var(--warnb);border-radius:10px;padding:.7rem .9rem;margin:1.4rem 0;font-size:.92rem}\n.src{font-size:.88rem;color:var(--mut);margin-top:1.4rem;border-top:1px solid var(--line);padding-top:.7rem}\npre{white-space:pre-wrap;word-wrap:break-word;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:.8rem;font-size:.9rem}\n.box{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:.2rem 1rem 1rem;margin:1rem 0}\n.hide{display:none}\n</style></head><body><main id="app"></main>\n<script>\nconst CARDS=__CARDS__;const ZONES=__ZONES__;\nconst zc=k=>(ZONES.find(z=>z.key===k)||{}).color||"#555";\nconst app=document.getElementById("app");\nconst esc=s=>s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;"}[c]));\nfunction home(){\n  let h=\'<h1>ATLAS Pocket</h1><p class="sub">Offline guide. Pick a button or search. \'+CARDS.length+\' cards.</p>\'+\n  \'<input type="search" id="q" placeholder="Search: bleeding, water, snake, battery..." autocomplete="off">\'+\n  \'<div id="res" class="res"></div><div id="main">\';\n  h+=\'<div class="zones">\'+ZONES.map(z=>\'<button class="zone" style="--c:\'+z.color+\'" onclick="location.hash=\\\'z-\'+encodeURIComponent(z.key)+\'\\\'">\'+esc(z.label)+\'<small>\'+esc(z.hint)+\' &middot; \'+CARDS.filter(c=>c.zone===z.key).length+(CARDS.filter(c=>c.zone===z.key).length==1?\' card\':\' cards\')+\'</small></button>\').join("")+\'</div>\';\n  h+=\'<div class="box"><h2 style="border:0">If you are unsure what to do first</h2><ol><li><b>Danger around you?</b> Get yourself and the person out of it.</li><li><b>Not breathing or no pulse?</b> Start CPR if you know how.</li><li><b>Heavy bleeding?</b> Card E01.</li><li><b>Cold, wet, or very hot?</b> Get to shelter. Card E03.</li><li><b>No safe water?</b> Card W01.</li></ol><p class="sub">Rule of thumb for how long people last: about 3 minutes without air, 3 hours in harsh weather without shelter, 3 days without water, 3 weeks without food. These are rough numbers.</p></div>\';\n  h+=\'<div class="box"><h2 style="border:0">Using this with the AI on your phone</h2><p>Open a card, tap <b>Copy for AI</b>, then paste into the chat and type your question after "MY QUESTION:". The AI will answer from the card instead of from memory. If the AI says the card does not cover it, find another card. If the AI contradicts the card, trust the card.</p></div>\';\n  h+=\'</div>\';\n  app.innerHTML=h;\n  const q=document.getElementById("q"),res=document.getElementById("res"),main=document.getElementById("main");\n  q.addEventListener("input",()=>{\n    const t=q.value.toLowerCase().trim().split(/\\s+/).filter(Boolean);\n    if(!t.length){res.innerHTML="";main.classList.remove("hide");return}\n    main.classList.add("hide");\n    const sc=CARDS.map(c=>{let s=0;const ti=c.title.toLowerCase(),kw=c.keywords.toLowerCase();\n      for(const w of t){if(ti.includes(w))s+=5;if(kw.includes(w))s+=3;if(c.search.includes(w))s+=1;}\n      return[s,c]}).filter(x=>x[0]>0).sort((a,b)=>b[0]-a[0]);\n    res.innerHTML=sc.length?sc.map(x=>row(x[1])).join(""):\'<p class="sub">No card found. Try another word.</p>\';\n  });\n}\nfunction row(c){return \'<a href="#\'+c.id+\'" style="--c:\'+zc(c.zone)+\'"><b>\'+c.id+\'</b><span>\'+esc(c.title)+\'</span></a>\'}\nfunction zone(k){\n  const z=ZONES.find(z=>z.key===k);if(!z)return home();\n  app.innerHTML=\'<a class="back" href="#">&larr; Home</a><h1>\'+esc(z.label)+\'</h1><p class="sub">\'+esc(z.hint)+\'</p><div class="list">\'+CARDS.filter(c=>c.zone===k).map(row).join("")+\'</div>\';\n}\nfunction card(id){\n  const c=CARDS.find(c=>c.id===id);if(!c)return home();\n  app.innerHTML=\'<a class="back" href="#z-\'+encodeURIComponent(c.zone)+\'">&larr; \'+esc((ZONES.find(z=>z.key===c.zone)||{}).label||"Back")+\'</a> <a class="back" href="#">Home</a>\'+\n  \'<div><span class="chip" style="--c:\'+zc(c.zone)+\'">\'+c.id+\'</span></div><h1>\'+esc(c.title)+\'</h1>\'+\n  \'<div class="tools"><button class="act" id="cp">Copy for AI</button><button class="act alt" id="tx">Show text</button></div><div id="cpmsg" class="sub"></div>\'+\n  \'<pre id="pre" class="hide"></pre>\'+c.figs+c.html+\n  \'<div class="note"><b>Status:</b> \'+esc(c.status)+\'</div><div class="src"><b>Source:</b> \'+esc(c.source)+\'</div>\';\n  document.getElementById("pre").textContent=c.ai;\n  document.getElementById("tx").onclick=()=>{const p=document.getElementById("pre");p.classList.toggle("hide")};\n  document.getElementById("cp").onclick=()=>copy(c.ai);\n  window.scrollTo(0,0);\n}\nfunction copy(t){\n  const m=document.getElementById("cpmsg");\n  const fb=()=>{const p=document.getElementById("pre");p.classList.remove("hide");const r=document.createRange();r.selectNodeContents(p);const s=getSelection();s.removeAllRanges();s.addRange(r);\n    let ok=false;try{ok=document.execCommand("copy")}catch(e){}\n    m.textContent=ok?"Copied. Paste it into the AI chat.":"Could not copy automatically. The text is selected below: long-press and choose Copy."};\n  if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(t).then(()=>m.textContent="Copied. Paste it into the AI chat.",fb)}else fb();\n}\nfunction route(){const h=decodeURIComponent(location.hash.slice(1));\n  if(!h)return home();if(h.startsWith("z-"))return zone(h.slice(2));card(h)}\naddEventListener("hashchange",route);route();\n</script></body></html>\n"""\n\nif __name__ == "__main__":\n    main()\n'

